147	            );
148	        }
149	
150	        const repo: Repository = { Id: id, Name: name, Url: cleanUrl };
151	        store.Repositories.push(repo);
152	        this.save(store);
153	
154	        if (credentialsWereStripped) {
155	            return { ...repo, credentialsStripped: true };
156	        }
157	        return repo;
