160	    /**
161	     * Updates the `Name` of an existing repository.
162	     *
163	     * @throws {Error} If no repository with the given ID exists.
164	     */
165	    update(id: string, params: { name: string }): Repository {
166	        const store = this.load();
167	        const index = store.Repositories.findIndex((r) => r.Id === id);
168	
169	        if (index === -1) {
170	            throw new NotFoundError(`Cannot update: repository with ID "${id}" does not exist.`);
171	        }
172	
173	        store.Repositories[index] = { ...store.Repositories[index], Name: params.name };
174	        this.save(store);
175	        return store.Repositories[index];
176	    }
