220	        const existing = store.Repositories[index];
221	        if (credentialId === null) {
222	            // Remove the CredentialId field entirely so the JSON stays clean.
223	            const { CredentialId: _removed, ...rest } = existing;
224	            store.Repositories[index] = rest as Repository;
225	        } else {
